contract InvMutTest {
    C c;

    constructor() { c = new C(address(this), address(this), address(this)); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(
        address _baseToken,
        address _nft,
        uint128 _virtualBaseTokenReserves,
        uint128 _virtualNftReserves,
        uint56 _changeFee,
        uint16 _feeRate,
        bytes32 _merkleRoot,
        bool _useStolenNftOracle,
        bool _payRoyalties
    ) public {
        require(_feeRate <= 5000, "fee rate too high");

        c.initialize(
            _baseToken,
            _nft,
            _virtualBaseTokenReserves,
            _virtualNftReserves,
            _changeFee,
            _feeRate,
            _merkleRoot,
            _useStolenNftOracle,
            _payRoyalties
        ); if (__ESBMC_reverted()) return;

        uint128 vbBefore = c.virtualBaseTokenReserves(); if (__ESBMC_reverted()) return;
        uint128 vnBefore = c.virtualNftReserves(); if (__ESBMC_reverted()) return;
        bytes32 mrBefore = c.merkleRoot(); if (__ESBMC_reverted()) return;
        uint16 frBefore = c.feeRate(); if (__ESBMC_reverted()) return;
        bool snBefore = c.useStolenNftOracle(); if (__ESBMC_reverted()) return;
        bool prBefore = c.payRoyalties(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.initialize(
            _baseToken,
            _nft,
            _virtualBaseTokenReserves,
            _virtualNftReserves,
            _changeFee,
            _feeRate,
            _merkleRoot,
            _useStolenNftOracle,
            _payRoyalties
        ); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(
            reverted &&
            c.initialized() &&
            c.virtualBaseTokenReserves() == vbBefore &&
            c.virtualNftReserves() == vnBefore &&
            c.merkleRoot() == mrBefore &&
            c.feeRate() == frBefore &&
            c.useStolenNftOracle() == snBefore &&
            c.payRoyalties() == prBefore
        );
    }

    receive() external payable {}
}

