pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PrivatePool} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PrivatePool c;

    function setUp() public {
        c = new PrivatePool(address(this), address(this), address(this));
    }

    function _run(address _baseToken, address _nft, uint128 _virtualBaseTokenReserves, uint128 _virtualNftReserves, uint56 _changeFee, uint16 _feeRate, bytes32 _merkleRoot, bool _useStolenNftOracle, bool _payRoyalties) internal {
        _feeRate = uint16(bound(uint256(_feeRate), 0, 5000));
        try c.initialize(
            _baseToken,
            _nft,
            _virtualBaseTokenReserves,
            _virtualNftReserves,
            _changeFee,
            _feeRate,
            _merkleRoot,
            _useStolenNftOracle,
            _payRoyalties
        ) {} catch { return; }
        uint128 vbBefore;
        try c.virtualBaseTokenReserves() returns (uint128 __r) { vbBefore = __r; } catch { return; }
        uint128 vnBefore;
        try c.virtualNftReserves() returns (uint128 __r) { vnBefore = __r; } catch { return; }
        bytes32 mrBefore;
        try c.merkleRoot() returns (bytes32 __r) { mrBefore = __r; } catch { return; }
        uint16 frBefore;
        try c.feeRate() returns (uint16 __r) { frBefore = __r; } catch { return; }
        bool snBefore;
        try c.useStolenNftOracle() returns (bool __r) { snBefore = __r; } catch { return; }
        bool prBefore;
        try c.payRoyalties() returns (bool __r) { prBefore = __r; } catch { return; }
        bool reverted;
        try c.initialize(
            _baseToken,
            _nft,
            _virtualBaseTokenReserves,
            _virtualNftReserves,
            _changeFee,
            _feeRate,
            _merkleRoot,
            _useStolenNftOracle,
            _payRoyalties
        ) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted &&
            c.initialized() &&
            c.virtualBaseTokenReserves() == vbBefore &&
            c.virtualNftReserves() == vnBefore &&
            c.merkleRoot() == mrBefore &&
            c.feeRate() == frBefore &&
            c.useStolenNftOracle() == snBefore &&
            c.payRoyalties() == prBefore);
    }

